protected override void OnModelCreating(ModelBuilder
modelBuilder)
{
base.OnModelCreating(modelBuilder);
modelBuilder.Seed<Artist>("./Data/artist.json");
modelBuilder.Seed<Genre>("./Data/genre.json");
